package com.arantec.castafiore.ui.activities

import android.Manifest
import android.content.ComponentName
import android.content.Intent
import android.content.ServiceConnection
import android.content.pm.PackageManager
import android.os.Build
import android.os.Bundle
import android.os.IBinder
import android.view.View
import androidx.activity.result.contract.ActivityResultContracts
import androidx.appcompat.app.AppCompatActivity
import androidx.core.content.ContextCompat
import androidx.navigation.NavOptions
import androidx.navigation.fragment.NavHostFragment
import androidx.navigation.ui.setupWithNavController
import androidx.navigation.findNavController
import com.arantec.castafiore.R
import com.arantec.castafiore.data.cache.CacheConfig
import com.arantec.castafiore.data.models.Song
import com.arantec.castafiore.data.repository.MusicRepository
import com.arantec.castafiore.databinding.ActivityMainBinding
import com.arantec.castafiore.service.MusicService
import com.arantec.castafiore.utils.ImageLoader
import com.arantec.castafiore.utils.StatusBarUtils
import com.arantec.castafiore.data.network.NavidromeClient
import com.arantec.castafiore.data.network.InFlightTracker
import com.arantec.castafiore.ui.helpers.HasContentState
import androidx.lifecycle.Lifecycle
import androidx.lifecycle.lifecycleScope
import androidx.lifecycle.repeatOnLifecycle
import kotlinx.coroutines.Job
import kotlinx.coroutines.delay
import kotlinx.coroutines.launch

class MainActivity : AppCompatActivity() {

    private lateinit var binding: ActivityMainBinding
    private lateinit var musicRepository: MusicRepository
    private var musicService: MusicService? = null
    private var isBound = false

    private val serviceConnection = object : ServiceConnection {
        override fun onServiceConnected(name: ComponentName?, service: IBinder?) {
            val binder = service as MusicService.MusicBinder
            musicService = binder.getService()
            isBound = true

            // Setup listeners
            musicService?.addPlaybackStateListener { isPlaying ->
                updatePlayPauseButton(isPlaying)
            }

            musicService?.addSongChangeListener { song ->
                updateMiniPlayer(song)
            }

            // Ensure mini player UI is populated even if song didn't change
            updateMiniPlayer(musicService?.getCurrentSong())
        }

        override fun onServiceDisconnected(name: ComponentName?) {
            musicService = null
            isBound = false
        }
    }

    private val notificationPermissionLauncher = registerForActivityResult(
        ActivityResultContracts.RequestPermission()
    ) { isGranted ->
        // No es crítico si el usuario no concede el permiso
        // La música seguirá funcionando sin notificaciones
    }

    // Global loading overlay control
    private var overlayVisible = false
    private var pendingShowJob: Job? = null
    private var lastShowStartAt: Long = 0L

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)

        musicRepository = MusicRepository.getInstance(this)

        // Check if configured
        if (!musicRepository.isConfigured()) {
            startActivity(Intent(this, SetupActivity::class.java))
            finish()
            return
        }

        // Initialize API client with saved server URL
        musicRepository.serverUrl?.let { NavidromeClient.initialize(it) }

        // Inicializar el sistema de cache
        CacheConfig.initialize(this)

        binding = ActivityMainBinding.inflate(layoutInflater)
        setContentView(binding.root)

        // Set consistent status bar color
        StatusBarUtils.setStatusBarColor(this)

        setupNavigationComponent()
        setupMiniPlayer()
        bindMusicService()
        requestNotificationPermission()

        // Observe global network state and toggle the overlay
        setupGlobalLoadingObserver()

        // Handle intent extras for navigation
        handleNavigationFromIntent()
    }

    override fun onNewIntent(intent: Intent) {
        super.onNewIntent(intent)
        // Update stored intent so handleNavigationFromIntent() reads the latest extras
        setIntent(intent)
        // React to navigation requests when MainActivity is reused (SINGLE_TOP/CLEAR_TOP)
        handleNavigationFromIntent()
    }

    private fun setupGlobalLoadingObserver() {
        // Recompute when in-flight state changes
        lifecycleScope.launch {
            repeatOnLifecycle(Lifecycle.State.STARTED) {
                InFlightTracker.isLoading.collect { isLoading ->
                    recomputeGlobalOverlay(isLoading)
                }
            }
        }

        // Recompute when destination changes
        val navHostFragment = supportFragmentManager.findFragmentById(R.id.nav_host_fragment) as NavHostFragment
        navHostFragment.navController.addOnDestinationChangedListener { _, _, _ ->
            recomputeGlobalOverlay(InFlightTracker.isLoading.value)
        }
    }

    private fun recomputeGlobalOverlay(isLoading: Boolean) {
        val hasContent = currentFragmentHasContent()
        val shouldShow = isLoading && !hasContent
        android.util.Log.d("GlobalLoader", "isLoading=$isLoading, hasContent=$hasContent, shouldShow=$shouldShow")
        if (shouldShow) {
            maybeShowOverlayWithDebounce()
        } else {
            hideOverlayRespectingMinShow()
        }
    }

    private fun currentFragmentHasContent(): Boolean {
        val navHost = supportFragmentManager.findFragmentById(R.id.nav_host_fragment) as? NavHostFragment
        val current = navHost?.childFragmentManager?.fragments?.lastOrNull { it.isVisible }
        val provider = current as? HasContentState
        // Default to false so the overlay appears unless the screen explicitly signals content
        return provider?.hasContent() ?: false
    }

    private fun maybeShowOverlayWithDebounce() {
        if (overlayVisible) return
        if (pendingShowJob != null) return
        pendingShowJob = lifecycleScope.launch {
            // Debounce to avoid flicker on super fast calls
            delay(150)
            // Ensure condition still holds
            if (InFlightTracker.isLoading.value && !currentFragmentHasContent()) {
                android.util.Log.d("GlobalLoader", "Showing overlay")
                binding.globalLoadingOverlay.visibility = View.VISIBLE
                overlayVisible = true
                lastShowStartAt = System.currentTimeMillis()
            }
            pendingShowJob = null
        }
    }

    private fun hideOverlayRespectingMinShow() {
        pendingShowJob?.cancel()
        pendingShowJob = null
        if (!overlayVisible) return
        val shownFor = System.currentTimeMillis() - lastShowStartAt
        val hideAction = {
            android.util.Log.d("GlobalLoader", "Hiding overlay")
            binding.globalLoadingOverlay.visibility = View.GONE
            overlayVisible = false
        }
        if (shownFor >= 200) {
            hideAction()
        } else {
            lifecycleScope.launch {
                delay(200 - shownFor)
                hideAction()
            }
        }
    }

    private fun setupNavigationComponent() {
        val navHostFragment = supportFragmentManager
            .findFragmentById(R.id.nav_host_fragment) as NavHostFragment
        val navController = navHostFragment.navController

        // Mantener sincronización visual (badges/selección) con NavigationUI
        binding.bottomNavigation.setupWithNavController(navController)

        // Forzar navegación al fragmento correspondiente siempre, sin importar el actual
        binding.bottomNavigation.setOnItemSelectedListener { item ->
            val options = NavOptions.Builder()
                // Volver al inicio del grafo para salir de detalles antes de cambiar de pestaña
                .setPopUpTo(navController.graph.startDestinationId, false)
                .setLaunchSingleTop(true)
                .setRestoreState(true)
                .build()

            try {
                if (navController.currentDestination?.id == item.itemId) {
                    // Ya estamos en el destino: limpiar cualquier pila interna si aplica
                    navController.popBackStack(item.itemId, false)
                } else {
                    navController.navigate(item.itemId, null, options)
                }
                true
            } catch (e: IllegalArgumentException) {
                // Si el destino no existe en el grafo
                android.util.Log.e("MainActivity", "Destino no encontrado para itemId=${item.itemId}", e)
                false
            }
        }

        // Al re-seleccionar la misma pestaña, volver al root de esa sección
        binding.bottomNavigation.setOnItemReselectedListener { item ->
            try {
                navController.popBackStack(item.itemId, false)
            } catch (_: Exception) { }
        }
    }

    private fun handleNavigationFromIntent() {
        val selectedTab = intent.getStringExtra("selected_tab")
        selectedTab?.let { tab ->
            val itemId = when (tab) {
                "home" -> R.id.homeFragment
                "search" -> R.id.searchFragment
                "library" -> R.id.libraryFragment
                else -> R.id.homeFragment
            }
            binding.bottomNavigation.selectedItemId = itemId
        }

        // Handle navigation from PlayerActivity to AlbumDetailFragment or ArtistDetailFragment
        val navigateTo = intent.getStringExtra("navigate_to")
        android.util.Log.d("MainActivity", "Received navigation intent - navigate_to: $navigateTo")

        when (navigateTo) {
            "album_detail" -> {
                val albumId = intent.getStringExtra("album_id")
                val albumName = intent.getStringExtra("album_name")
                android.util.Log.d("MainActivity", "Album navigation - albumId: $albumId, albumName: $albumName")
                if (albumId != null && albumName != null) {
                    navigateToAlbumDetail(albumId, albumName)
                }
            }
            "artist_detail" -> {
                val artistId = intent.getStringExtra("artist_id")
                val artistName = intent.getStringExtra("artist_name")
                android.util.Log.d("MainActivity", "Artist navigation - artistId: $artistId, artistName: $artistName")
                if (artistId != null && artistName != null) {
                    navigateToArtistDetail(artistId, artistName)
                }
            }
        }
    }

    private fun navigateToAlbumDetail(albumId: String, albumName: String) {
        // Usar Navigation Component para navegar al AlbumDetailFragment
        android.util.Log.d("MainActivity", "navigateToAlbumDetail called with albumId: $albumId, albumName: $albumName")
        try {
            val navController = findNavController(R.id.nav_host_fragment)

            // Obtener información adicional del artista si está disponible
            val artistName = intent.getStringExtra("artist_name") ?: ""
            val artistId = intent.getStringExtra("artist_id") ?: ""

            // Crear un objeto Album con toda la información disponible
            // El AlbumDetailFragment espera un objeto Album completo
            val album = com.arantec.castafiore.data.models.Album(
                id = albumId,
                name = albumName,
                artist = artistName, // Ahora tenemos el nombre del artista
                artistId = artistId, // Ahora tenemos el ID del artista
                songCount = 0, // Se cargará desde el servicio
                duration = 0, // Se cargará desde el servicio
                coverArt = albumId, // Usar el albumId como coverArt para que pueda cargar la imagen
                year = null,
                genre = null,
                songs = null
            )

            val bundle = Bundle().apply {
                putParcelable("album", album)
            }

            android.util.Log.d("MainActivity", "Attempting to navigate to albumDetailFragment with Album object (artist: $artistName)")
            navController.navigate(R.id.albumDetailFragment, bundle)
            android.util.Log.d("MainActivity", "Navigation to albumDetailFragment completed successfully")
        } catch (e: Exception) {
            android.util.Log.e("MainActivity", "Error navigating to album detail: ${e.message}", e)
        }
    }

    private fun navigateToArtistDetail(artistId: String, artistName: String) {
        // Usar Navigation Component para navegar al ArtistDetailFragment
        android.util.Log.d("MainActivity", "navigateToArtistDetail called with artistId: $artistId, artistName: $artistName")
        try {
            val navController = findNavController(R.id.nav_host_fragment)
            // Necesitamos usar SafeArgs para pasar los parámetros al ArtistDetailFragment
            // Por ahora, usando Bundle para compatibilidad
            val bundle = Bundle().apply {
                putString("artistId", artistId)
                putString("artistName", artistName)
            }
            android.util.Log.d("MainActivity", "Attempting to navigate to artistDetailFragment with bundle")
            navController.navigate(R.id.artistDetailFragment, bundle)
            android.util.Log.d("MainActivity", "Navigation to artistDetailFragment completed successfully")
        } catch (e: Exception) {
            android.util.Log.e("MainActivity", "Error navigating to artist detail: ${e.message}", e)
        }
    }

    private fun setupMiniPlayer() {
        binding.btnPlayPause.setOnClickListener {
            musicService?.togglePlayPause()
        }

        // New: Next button handler
        binding.btnNext.setOnClickListener {
            musicService?.next()
        }

        binding.playerContainer.setOnClickListener {
            // Launch PlayerActivity for full-screen player experience
            try {
                val intent = Intent(this, PlayerActivity::class.java)
                startActivity(intent)
            } catch (_: Exception) {
                // Handle launch error silently
            }
        }
    }

    private fun bindMusicService() {
        val intent = Intent(this, MusicService::class.java)
        bindService(intent, serviceConnection, android.content.Context.BIND_AUTO_CREATE)
    }

    private fun requestNotificationPermission() {
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU) {
            if (ContextCompat.checkSelfPermission(
                    this,
                    Manifest.permission.POST_NOTIFICATIONS
                ) != PackageManager.PERMISSION_GRANTED
            ) {
                notificationPermissionLauncher.launch(Manifest.permission.POST_NOTIFICATIONS)
            }
        }
    }

    private fun updatePlayPauseButton(isPlaying: Boolean) {
        val iconRes = if (isPlaying) R.drawable.ic_pause else R.drawable.ic_play
        binding.btnPlayPause.setImageResource(iconRes)
    }

    private fun updateMiniPlayer(song: Song?) {
        if (song != null) {
            binding.playerContainer.visibility = View.VISIBLE
            binding.tvSongTitle.text = song.title
            binding.tvArtistName.text = song.artist

            // Preferir portada local si disponible; fallback a URL con ImageLoader
            try {
                val dm = com.arantec.castafiore.data.download.SongDownloadManager.getInstance(this)
                val localCoverPath = try { dm.createCoverPath(song) } catch (_: Exception) { null }
                var usedLocal = false
                if (!localCoverPath.isNullOrEmpty()) {
                    val file = java.io.File(localCoverPath)
                    if (file.exists()) {
                        val bmp = android.graphics.BitmapFactory.decodeFile(localCoverPath)
                        if (bmp != null) {
                            binding.ivAlbumArt.setImageBitmap(bmp)
                            usedLocal = true
                        }
                    }
                }
                if (!usedLocal) {
                    val (username, token, salt) = musicRepository.getAuthParams()
                    val coverId = song.coverArt ?: song.albumId
                    val coverUrl = coverId?.let { id ->
                        ImageLoader.buildCoverArtUrl(
                            musicRepository.serverUrl!!,
                            id,
                            username,
                            token,
                            salt,
                            500 // match PlayerActivity size to share cache offline
                        )
                    }
                    ImageLoader.loadThumbnail(this, binding.ivAlbumArt, coverUrl)
                }
            } catch (_: Exception) {
                // Si falla, usar placeholder
                binding.ivAlbumArt.setImageResource(R.drawable.ic_album_placeholder)
            }
        } else {
            binding.playerContainer.visibility = View.GONE
        }
    }

    override fun onResume() {
        super.onResume()
        // Ensure overlay state is consistent after returning from another Activity (e.g., PlayerActivity)
        recomputeGlobalOverlay(com.arantec.castafiore.data.network.InFlightTracker.isLoading.value)
        // When returning from PlayerActivity, refresh mini player artwork/state
        if (isBound) {
            updateMiniPlayer(musicService?.getCurrentSong())
            musicService?.let { updatePlayPauseButton(it.isPlaying()) }
        }
    }

    override fun onPause() {
        // Hide overlay when going to background to avoid a stuck scrim if any in-flight state glitches
        hideOverlayRespectingMinShow()
        super.onPause()
    }

    override fun onStop() {
        // Extra safety: ensure overlay is hidden when activity stops
        hideOverlayRespectingMinShow()
        super.onStop()
    }

    override fun onDestroy() {
        super.onDestroy()
        if (isBound) {
            unbindService(serviceConnection)
            isBound = false
        }
    }
}

package com.arantec.castafiore.ui.activities

import android.Manifest
import android.content.ComponentName
import android.content.Intent
import android.content.ServiceConnection
import android.content.pm.PackageManager
import android.os.Build
import android.os.Bundle
import android.os.IBinder
import android.view.View
import androidx.activity.result.contract.ActivityResultContracts
import androidx.appcompat.app.AppCompatActivity
import androidx.core.content.ContextCompat
import androidx.navigation.NavOptions
import androidx.navigation.fragment.NavHostFragment
import androidx.navigation.ui.setupWithNavController
import androidx.navigation.findNavController
import com.arantec.castafiore.R
import com.arantec.castafiore.data.cache.CacheConfig
import com.arantec.castafiore.data.models.Song
import com.arantec.castafiore.data.repository.MusicRepository
import com.arantec.castafiore.databinding.ActivityMainBinding
import com.arantec.castafiore.service.MusicService
import com.arantec.castafiore.utils.ImageLoader
import com.arantec.castafiore.utils.StatusBarUtils
import com.arantec.castafiore.data.network.NavidromeClient
import com.arantec.castafiore.data.network.InFlightTracker
import com.arantec.castafiore.ui.helpers.HasContentState
import com.arantec.castafiore.ui.helpers.LoadingHost
import androidx.lifecycle.Lifecycle
import androidx.lifecycle.lifecycleScope
import androidx.lifecycle.repeatOnLifecycle
import kotlinx.coroutines.Job
import kotlinx.coroutines.delay
import kotlinx.coroutines.launch

class MainActivity : AppCompatActivity(), LoadingHost {

    private lateinit var binding: ActivityMainBinding
    private lateinit var musicRepository: MusicRepository
    private var musicService: MusicService? = null
    private var isBound = false

    private val serviceConnection = object : ServiceConnection {
        override fun onServiceConnected(name: ComponentName?, service: IBinder?) {
            val binder = service as MusicService.MusicBinder
            musicService = binder.getService()
            isBound = true

            // Setup listeners
            musicService?.addPlaybackStateListener { isPlaying ->
                updatePlayPauseButton(isPlaying)
            }

            musicService?.addSongChangeListener { song ->
                updateMiniPlayer(song)
            }

            // Ensure mini player UI is populated even if song didn't change
            updateMiniPlayer(musicService?.getCurrentSong())
        }

        override fun onServiceDisconnected(name: ComponentName?) {
            musicService = null
            isBound = false
        }
    }

    private val notificationPermissionLauncher = registerForActivityResult(
        ActivityResultContracts.RequestPermission()
    ) { isGranted ->
        // No es crítico si el usuario no concede el permiso
        // La música seguirá funcionando sin notificaciones
    }

    // Global loading overlay control
    private var overlayVisible = false
    private var pendingShowJob: Job? = null
    private var lastShowStartAt: Long = 0L

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)

        musicRepository = MusicRepository.getInstance(this)

        // Check if configured
        if (!musicRepository.isConfigured()) {
            startActivity(Intent(this, SetupActivity::class.java))
            finish()
            return
        }

        // Initialize API client with saved server URL
        musicRepository.serverUrl?.let { NavidromeClient.initialize(it) }

        // Inicializar el sistema de cache
        CacheConfig.initialize(this)

        binding = ActivityMainBinding.inflate(layoutInflater)
        setContentView(binding.root)

        // Set consistent status bar color
        StatusBarUtils.setStatusBarColor(this)

        setupNavigationComponent()
        setupMiniPlayer()
        bindMusicService()
        requestNotificationPermission()

        // Observe global network state and toggle the overlay
        setupGlobalLoadingObserver()

        // Handle intent extras for navigation
        handleNavigationFromIntent()
    }

    override fun onNewIntent(intent: Intent) {
        super.onNewIntent(intent)
        // Update stored intent so handleNavigationFromIntent() reads the latest extras
        setIntent(intent)
        // React to navigation requests when MainActivity is reused (SINGLE_TOP/CLEAR_TOP)
        handleNavigationFromIntent()
    }

    // LoadingHost implementation to allow child fragments to control the overlay explicitly
    override fun showGlobalLoading(show: Boolean) {
        // Cancel any pending debounced show to avoid race conditions
        pendingShowJob?.cancel()
        pendingShowJob = null
        if (show) {
            binding.globalLoadingOverlay.visibility = View.VISIBLE
            overlayVisible = true
            lastShowStartAt = System.currentTimeMillis()
        } else {
            // Hide respecting minimum show time to avoid flicker
            hideOverlayRespectingMinShow()
        }
    }

    override fun isGlobalLoadingVisible(): Boolean = overlayVisible

    private fun setupGlobalLoadingObserver() {
        // Recompute when in-flight state changes
        lifecycleScope.launch {
            repeatOnLifecycle(Lifecycle.State.STARTED) {
                InFlightTracker.isLoading.collect { isLoading ->
                    recomputeGlobalOverlay(isLoading)
                }
            }
        }

        // Recompute when destination changes
        val navHostFragment = supportFragmentManager.findFragmentById(R.id.nav_host_fragment) as NavHostFragment
        navHostFragment.navController.addOnDestinationChangedListener { _, _, _ ->
            recomputeGlobalOverlay(InFlightTracker.isLoading.value)
        }
    }

    private fun recomputeGlobalOverlay(isLoading: Boolean) {
        val hasContent = currentFragmentHasContent()
        val shouldShow = isLoading && !hasContent
        android.util.Log.d("GlobalLoader", "isLoading=$isLoading, hasContent=$hasContent, shouldShow=$shouldShow")
        if (shouldShow) {
            maybeShowOverlayWithDebounce()
        } else {
            hideOverlayRespectingMinShow()
        }
    }

    private fun currentFragmentHasContent(): Boolean {
        val navHost = supportFragmentManager.findFragmentById(R.id.nav_host_fragment) as? NavHostFragment
        val current = navHost?.childFragmentManager?.fragments?.lastOrNull { it.isVisible }
        val provider = current as? HasContentState
        // Default to false so the overlay appears unless the screen explicitly signals content
        return provider?.hasContent() ?: false
    }

    private fun maybeShowOverlayWithDebounce() {
        if (overlayVisible) return
        if (pendingShowJob != null) return
        pendingShowJob = lifecycleScope.launch {
            // Debounce to avoid flicker on super fast calls
            delay(150)
            // Ensure condition still holds
            if (InFlightTracker.isLoading.value && !currentFragmentHasContent()) {
                android.util.Log.d("GlobalLoader", "Showing overlay")
                binding.globalLoadingOverlay.visibility = View.VISIBLE
                overlayVisible = true
                lastShowStartAt = System.currentTimeMillis()
            }
            pendingShowJob = null
        }
    }

    private fun hideOverlayRespectingMinShow() {
        pendingShowJob?.cancel()
        pendingShowJob = null
        if (!overlayVisible) return
        val shownFor = System.currentTimeMillis() - lastShowStartAt
        val hideAction = {
            android.util.Log.d("GlobalLoader", "Hiding overlay")
            binding.globalLoadingOverlay.visibility = View.GONE
            overlayVisible = false
        }
        if (shownFor >= 200) {
            hideAction()
        } else {
            lifecycleScope.launch {
                delay(200 - shownFor)
                hideAction()
            }
        }
    }

    private fun setupNavigationComponent() {
        val navHostFragment = supportFragmentManager
            .findFragmentById(R.id.nav_host_fragment) as NavHostFragment
        val navController = navHostFragment.navController

        // Mantener sincronización visual (badges/selección) con NavigationUI
        binding.bottomNavigation.setupWithNavController(navController)

        // Forzar navegación al fragmento correspondiente siempre, sin importar el actual
        binding.bottomNavigation.setOnItemSelectedListener { item ->
            val options = NavOptions.Builder()
                // Volver al inicio del grafo para salir de detalles antes de cambiar de pestaña
                .setPopUpTo(navController.graph.startDestinationId, false)
                .setLaunchSingleTop(true)
                .setRestoreState(true)
                .build()

            try {
                if (navController.currentDestination?.id == item.itemId) {
                    // Ya estamos en el destino: limpiar cualquier pila interna si aplica
                    navController.popBackStack(item.itemId, false)
                } else {
                    navController.navigate(item.itemId, null, options)
                }
                true
            } catch (e: IllegalArgumentException) {
                // Si el destino no existe en el grafo
                android.util.Log.e("MainActivity", "Destino no encontrado para itemId=${item.itemId}", e)
                false
            }
        }

        // Al re-seleccionar la misma pestaña, volver al root de esa sección
        binding.bottomNavigation.setOnItemReselectedListener { item ->
            try {
                navController.popBackStack(item.itemId, false)
            } catch (_: Exception) { }
        }
    }

    private fun handleNavigationFromIntent() {
        val selectedTab = intent.getStringExtra("selected_tab")
        selectedTab?.let { tab ->
            val itemId = when (tab) {
                "home" -> R.id.homeFragment
                "search" -> R.id.searchFragment
                "library" -> R.id.libraryFragment
                else -> R.id.homeFragment
            }
            binding.bottomNavigation.selectedItemId = itemId
        }

        // Handle navigation from PlayerActivity to AlbumDetailFragment or ArtistDetailFragment
        val navigateTo = intent.getStringExtra("navigate_to")
        android.util.Log.d("MainActivity", "Received navigation intent - navigate_to: $navigateTo")

        when (navigateTo) {
            "album_detail" -> {
                val albumId = intent.getStringExtra("album_id")
                val albumName = intent.getStringExtra("album_name")
                android.util.Log.d("MainActivity", "Album navigation - albumId: $albumId, albumName: $albumName")
                if (albumId != null && albumName != null) {
                    navigateToAlbumDetail(albumId, albumName)
                }
            }
            "artist_detail" -> {
                val artistId = intent.getStringExtra("artist_id")
                val artistName = intent.getStringExtra("artist_name")
                android.util.Log.d("MainActivity", "Artist navigation - artistId: $artistId, artistName: $artistName")
                if (artistId != null && artistName != null) {
                    navigateToArtistDetail(artistId, artistName)
                }
            }
        }
    }

    private fun navigateToAlbumDetail(albumId: String, albumName: String) {
        // Usar Navigation Component para navegar al AlbumDetailFragment
        android.util.Log.d("MainActivity", "navigateToAlbumDetail called with albumId: $albumId, albumName: $albumName")
        try {
            val navController = findNavController(R.id.nav_host_fragment)

            // Obtener información adicional del artista si está disponible
            val artistName = intent.getStringExtra("artist_name") ?: ""
            val artistId = intent.getStringExtra("artist_id") ?: ""

            // Crear un objeto Album con toda la información disponible
            // El AlbumDetailFragment espera un objeto Album completo
            val album = com.arantec.castafiore.data.models.Album(
                id = albumId,
                name = albumName,
                artist = artistName, // Ahora tenemos el nombre del artista
                artistId = artistId, // Ahora tenemos el ID del artista
                songCount = 0, // Se cargará desde el servicio
                duration = 0, // Se cargará desde el servicio
                coverArt = albumId, // Usar el albumId como coverArt para que pueda cargar la imagen
                year = null,
                genre = null,
                songs = null
            )

            val bundle = Bundle().apply {
                putParcelable("album", album)
            }

            android.util.Log.d("MainActivity", "Attempting to navigate to albumDetailFragment with Album object (artist: $artistName)")
            navController.navigate(R.id.albumDetailFragment, bundle)
            android.util.Log.d("MainActivity", "Navigation to albumDetailFragment completed successfully")
        } catch (e: Exception) {
            android.util.Log.e("MainActivity", "Error navigating to album detail: ${e.message}", e)
        }
    }

    private fun navigateToArtistDetail(artistId: String, artistName: String) {
        // Usar Navigation Component para navegar al ArtistDetailFragment
        android.util.Log.d("MainActivity", "navigateToArtistDetail called with artistId: $artistId, artistName: $artistName")
        try {
            val navController = findNavController(R.id.nav_host_fragment)
            // Necesitamos usar SafeArgs para pasar los parámetros al ArtistDetailFragment
            // Por ahora, usando Bundle para compatibilidad
            val bundle = Bundle().apply {
                putString("artistId", artistId)
                putString("artistName", artistName)
            }
            android.util.Log.d("MainActivity", "Attempting to navigate to artistDetailFragment with bundle")
            navController.navigate(R.id.artistDetailFragment, bundle)
            android.util.Log.d("MainActivity", "Navigation to artistDetailFragment completed successfully")
        } catch (e: Exception) {
            android.util.Log.e("MainActivity", "Error navigating to artist detail: ${e.message}", e)
        }
    }

    private fun setupMiniPlayer() {
        binding.btnPlayPause.setOnClickListener {
            musicService?.togglePlayPause()
        }

        // New: Next button handler
        binding.btnNext.setOnClickListener {
            musicService?.next()
        }

        binding.playerContainer.setOnClickListener {
            // Launch PlayerActivity for full-screen player experience
            try {
                val intent = Intent(this, PlayerActivity::class.java)
                startActivity(intent)
            } catch (_: Exception) {
                // Handle launch error silently
            }
        }
    }

    private fun bindMusicService() {
        val intent = Intent(this, MusicService::class.java)
        bindService(intent, serviceConnection, android.content.Context.BIND_AUTO_CREATE)
    }

    private fun requestNotificationPermission() {
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU) {
            if (ContextCompat.checkSelfPermission(
                    this,
                    Manifest.permission.POST_NOTIFICATIONS
                ) != PackageManager.PERMISSION_GRANTED
            ) {
                notificationPermissionLauncher.launch(Manifest.permission.POST_NOTIFICATIONS)
            }
        }
    }

    private fun updatePlayPauseButton(isPlaying: Boolean) {
        val iconRes = if (isPlaying) R.drawable.ic_pause else R.drawable.ic_play
        binding.btnPlayPause.setImageResource(iconRes)
    }

    private fun updateMiniPlayer(song: Song?) {
        if (song != null) {
            binding.playerContainer.visibility = View.VISIBLE
            binding.tvSongTitle.text = song.title
            binding.tvArtistName.text = song.artist

            // Preferir portada local si disponible; fallback a URL con ImageLoader
            try {
                val dm = com.arantec.castafiore.data.download.SongDownloadManager.getInstance(this)
                val localCoverPath = try { dm.createCoverPath(song) } catch (_: Exception) { null }
                var usedLocal = false
                if (!localCoverPath.isNullOrEmpty()) {
                    val file = java.io.File(localCoverPath)
                    if (file.exists()) {
                        val bmp = android.graphics.BitmapFactory.decodeFile(localCoverPath)
                        if (bmp != null) {
                            binding.ivAlbumArt.setImageBitmap(bmp)
                            usedLocal = true
                        }
                    }
                }
                if (!usedLocal) {
                    val (username, token, salt) = musicRepository.getAuthParams()
                    val coverId = song.coverArt ?: song.albumId
                    val coverUrl = coverId?.let { id ->
                        ImageLoader.buildCoverArtUrl(
                            musicRepository.serverUrl!!,
                            id,
                            username,
                            token,
                            salt,
                            500 // match PlayerActivity size to share cache offline
                        )
                    }
                    ImageLoader.loadThumbnail(this, binding.ivAlbumArt, coverUrl)
                }
            } catch (_: Exception) {
                // Si falla, usar placeholder
                binding.ivAlbumArt.setImageResource(R.drawable.ic_album_placeholder)
            }
        } else {
            binding.playerContainer.visibility = View.GONE
        }
    }

    override fun onResume() {
        super.onResume()
        // Ensure overlay state is consistent after returning from another Activity (e.g., PlayerActivity)
        recomputeGlobalOverlay(com.arantec.castafiore.data.network.InFlightTracker.isLoading.value)
        // When returning from PlayerActivity, refresh mini player artwork/state
        if (isBound) {
            updateMiniPlayer(musicService?.getCurrentSong())
            musicService?.let { updatePlayPauseButton(it.isPlaying()) }
        }
    }

    override fun onPause() {
        // Hide overlay when going to background to avoid a stuck scrim if any in-flight state glitches
        hideOverlayRespectingMinShow()
        super.onPause()
    }

    override fun onStop() {
        // Extra safety: ensure overlay is hidden when activity stops
        hideOverlayRespectingMinShow()
        super.onStop()
    }

    override fun onDestroy() {
        super.onDestroy()
        if (isBound) {
            unbindService(serviceConnection)
            isBound = false
        }
    }
}

package com.arantec.castafiore.ui.fragments

import android.os.Bundle
import android.view.LayoutInflater
import android.view.View
import android.view.ViewGroup
import androidx.fragment.app.Fragment
import androidx.navigation.fragment.findNavController
import androidx.recyclerview.widget.LinearLayoutManager
import androidx.lifecycle.lifecycleScope
import kotlinx.coroutines.launch
import com.arantec.castafiore.R
import com.arantec.castafiore.databinding.FragmentLibraryBinding
import com.arantec.castafiore.ui.adapters.LibraryAdapter
import com.arantec.castafiore.data.models.LibraryItem
import com.arantec.castafiore.data.models.LibraryItemType
import com.arantec.castafiore.data.models.Album
import com.arantec.castafiore.data.models.Playlist
import com.arantec.castafiore.data.repository.MusicRepository
import com.arantec.castafiore.utils.ImageLoader
import com.arantec.castafiore.utils.StatusBarUtils
import com.google.android.material.chip.Chip
import com.arantec.castafiore.data.download.SongDownloadManager
import com.arantec.castafiore.utils.PlaylistFavoritesManager
import java.io.File
import com.arantec.castafiore.ui.helpers.HasContentState
import kotlinx.coroutines.sync.Mutex
import kotlinx.coroutines.sync.withLock

class LibraryFragment : Fragment(), HasContentState {

    private var _binding: FragmentLibraryBinding? = null
    private val binding get() = _binding!!

    private lateinit var libraryAdapter: LibraryAdapter
    private lateinit var musicRepository: MusicRepository
    private var currentFilter = "all"

    // Listas de datos separadas por tipo
    private var allItems = mutableListOf<LibraryItem>()
    private var playlists: List<LibraryItem> = emptyList()
    private var albums = mutableListOf<LibraryItem>()
    private var artists = mutableListOf<LibraryItem>()

    // Mapas para mantener referencias a los objetos completos
    private var albumsMap = mutableMapOf<String, Album>()
    private var playlistsMap = mutableMapOf<String, Playlist>()

    // Mutex para evitar condiciones de carrera al actualizar playlists
    private val playlistsMutex = Mutex()

    // Descargas
    private var downloads = mutableListOf<LibraryItem>()
    private var downloadsComputed = false
    private var downloadedAlbumsCache = mutableMapOf<String, Boolean>()
    private var downloadedPlaylistsCache = mutableMapOf<String, Boolean>()
    // Estado para evitar parpadeo y actualizaciones redundantes
    private var lastDownloadsVisible: Boolean = false
    private var lastDownloadedIds: Set<String> = emptySet()

    override fun hasContent(): Boolean {
        return this::libraryAdapter.isInitialized && libraryAdapter.itemCount > 0
    }

    override fun onCreateView(
        inflater: LayoutInflater,
        container: ViewGroup?,
        savedInstanceState: Bundle?
    ): View {
        _binding = FragmentLibraryBinding.inflate(inflater, container, false)
        return binding.root
    }

    override fun onViewCreated(view: View, savedInstanceState: Bundle?) {
        super.onViewCreated(view, savedInstanceState)

        musicRepository = MusicRepository.getInstance(requireContext())

        // Asegurar que el contenido no se dibuje bajo la status bar, sin añadir insets inferiores
        StatusBarUtils.applyStatusBarTopPadding(binding.root)

        // Restaurar filtro si viene de estado guardado
        savedInstanceState?.getString("currentFilter")?.let { restored ->
            currentFilter = restored
        }

        setupRecyclerView()
        setupFilters()
        setupControls()

        // Asegurar que el chip resaltado corresponda al filtro actual
        applyCheckedChipFromFilter()

        loadInitialData()
    }

    private fun setupRecyclerView() {
        libraryAdapter = LibraryAdapter { item ->
            handleItemClick(item)
        }

        binding.rvLibraryItems.apply {
            layoutManager = LinearLayoutManager(requireContext())
            adapter = libraryAdapter
        }

        // Asegurar que el adapter nuevo conozca los IDs descargados ya calculados
        if (lastDownloadedIds.isNotEmpty()) {
            libraryAdapter.updateDownloadedIds(lastDownloadedIds)
        }
    }

    private fun setupFilters() {
        // Configurar chips de filtros con manejo mejorado
        binding.chipAll.setOnClickListener {
            selectChip(binding.chipAll, "all")
        }

        binding.chipPlaylists.setOnClickListener {
            selectChip(binding.chipPlaylists, "playlists")
        }

        binding.chipAlbums.setOnClickListener {
            selectChip(binding.chipAlbums, "albums")
        }

        binding.chipArtists.setOnClickListener {
            selectChip(binding.chipArtists, "artists")
        }

        binding.chipDownloads.setOnClickListener {
            selectChip(binding.chipDownloads, "downloads")
        }
    }

    private fun selectChip(selectedChip: Chip, filter: String) {
        // Desmarcar todos los chips sin disparar listeners
        val chips = listOf(
            binding.chipAll,
            binding.chipDownloads,
            binding.chipPlaylists,
            binding.chipAlbums,
            binding.chipArtists
        )
        chips.forEach { chip ->
            chip.isChecked = false
        }

        // Marcar el chip seleccionado
        selectedChip.isChecked = true

        // Aplicar filtro
        currentFilter = filter
        filterContent()

        // Actualizar colores visuales
        updateChipColors()
    }

    private fun updateChipColors() {
        val primaryColor = androidx.core.content.ContextCompat.getColor(requireContext(), R.color.primary)
        val onPrimaryColor = androidx.core.content.ContextCompat.getColor(requireContext(), R.color.on_primary)
        val onSurfaceColor = androidx.core.content.ContextCompat.getColor(requireContext(), R.color.on_surface)
        val outlineColor = androidx.core.content.ContextCompat.getColor(requireContext(), R.color.outline)

        val chips = listOf(
            binding.chipAll,
            binding.chipDownloads,
            binding.chipPlaylists,
            binding.chipAlbums,
            binding.chipArtists
        )

        chips.forEach { chip ->
            if (chip.isChecked) {
                // Selected: filled primary background, white text, no stroke
                chip.chipBackgroundColor = android.content.res.ColorStateList.valueOf(primaryColor)
                chip.setTextColor(onPrimaryColor)
                chip.chipStrokeColor = android.content.res.ColorStateList.valueOf(primaryColor)
                chip.chipStrokeWidth = 0f
                chip.isChipIconVisible = false
            } else {
                // Unselected: transparent background, on-surface text, outline stroke
                chip.chipBackgroundColor = android.content.res.ColorStateList.valueOf(android.graphics.Color.TRANSPARENT)
                chip.setTextColor(onSurfaceColor)
                chip.chipStrokeColor = android.content.res.ColorStateList.valueOf(outlineColor)
                chip.chipStrokeWidth = 1f
                chip.isChipIconVisible = false
            }
        }
    }

    private fun applyCheckedChipFromFilter() {
        // Establecer el checked real según el filtro actual y luego pintar
        val isAll = currentFilter == "all"
        val isPlaylists = currentFilter == "playlists"
        val isAlbums = currentFilter == "albums"
        val isArtists = currentFilter == "artists"
        val isDownloads = currentFilter == "downloads"

        binding.chipAll.isChecked = isAll
        binding.chipPlaylists.isChecked = isPlaylists
        binding.chipAlbums.isChecked = isAlbums
        binding.chipArtists.isChecked = isArtists
        binding.chipDownloads.isChecked = isDownloads

        updateChipColors()
    }

    private fun setupControls() {
        binding.tvSortBy.setOnClickListener {
            // TODO: Mostrar opciones de ordenamiento
        }

        binding.btnViewMode.setOnClickListener {
            // TODO: Cambiar entre vista lista y cuadrícula
        }

        binding.actionLibraryToSearch.setOnClickListener {
            // Navegar al buscador
            findNavController().navigate(R.id.action_library_to_search)
        }
    }

    private fun loadInitialData() {
        // Only show local loader if we already have content (refresh behavior)
        if (hasContent()) {
            showLoading(true)
        }

        viewLifecycleOwner.lifecycleScope.launch {
            try {
                // Cargar datos por separado
                loadPlaylists()
                loadAlbums()
                loadArtists()

                // Una vez cargado todo, construir lista completa y mostrar contenido
                buildAllItemsList()
                filterContent()

                // Actualizar visibilidad del chip de Descargados (forzar primer cálculo)
                updateDownloadsChipVisibility(force = true)

            } catch (e: Exception) {
                showError("Error al cargar la biblioteca: ${e.message}")
            } finally {
                showLoading(false)
            }
        }
    }

    private suspend fun loadPlaylists() {
        try {
            // Construir listas locales para asignar de forma atómica y evitar duplicados por cargas concurrentes
            val newPlaylists = mutableListOf<LibraryItem>()
            val newPlaylistsMap = mutableMapOf<String, Playlist>()

            // Conjunto para evitar duplicados por ID (robusto ante respuestas repetidas de API)
            val seenPlaylistIds = mutableSetOf<String>()
            // Siempre agregar "Canciones que te gustan" primero
            newPlaylists.add(
                LibraryItem(
                    id = "liked_songs",
                    title = "Canciones que te gustan",
                    subtitle = "Playlist • Tus favoritas",
                    imageUrl = null,
                    type = LibraryItemType.LIKED_SONGS
                )
            )
            seenPlaylistIds.add("liked_songs")

            // Luego cargar las playlists de la API
            val result = musicRepository.getPlaylists()
            result.onSuccess { playlistsFromApi ->
                val dm = SongDownloadManager.getInstance(requireContext())
                val favorites = PlaylistFavoritesManager.getFavorites(requireContext())

                // 1) Playlists privadas (siempre)
                playlistsFromApi.filter { !it.public }.forEach { playlist ->
                    if (seenPlaylistIds.add(playlist.id)) {
                        val subtitle = "${playlist.songCount} canciones"

                        // Construir URL de imagen si la playlist tiene coverArt
                        var imageUrl: String? = null
                        if (playlist.coverArt != null) {
                            val (username, token, salt) = musicRepository.getAuthParams()
                            imageUrl = playlist.getCoverArtUrl(
                                musicRepository.serverUrl!!,
                                username,
                                token,
                                salt,
                                200
                            )
                        }

                        newPlaylists.add(
                            LibraryItem(
                                id = playlist.id,
                                title = playlist.name,
                                subtitle = "Playlist • $subtitle",
                                imageUrl = imageUrl,
                                type = LibraryItemType.PLAYLIST
                            )
                        )

                        // Agregar al mapa de playlists
                        newPlaylistsMap[playlist.id] = playlist
                    }
                }

                // 2) Playlists públicas descargadas: incluir también en listas principales
                playlistsFromApi.filter { it.public }.forEach { playlist ->
                    // Comprobar si está completamente descargada
                    var fullyDownloaded = false
                    try {
                        musicRepository.getPlaylistSongs(playlist.id).onSuccess { songs ->
                            fullyDownloaded = songs.isNotEmpty() && songs.all { song ->
                                val path = dm.createDownloadPath(song)
                                java.io.File(path).exists()
                            }
                        }
                    } catch (_: Exception) { /* ignore */ }

                    if (fullyDownloaded) {
                        if (seenPlaylistIds.add(playlist.id)) {
                            var imageUrl: String? = null
                            if (playlist.coverArt != null && musicRepository.serverUrl != null) {
                                val (u, t, s) = musicRepository.getAuthParams()
                                imageUrl = playlist.getCoverArtUrl(musicRepository.serverUrl!!, u, t, s, 200)
                            }
                            val subtitle = if (playlist.songCount > 0) "Playlist • ${playlist.songCount} canciones" else "Playlist"
                            newPlaylists.add(
                                LibraryItem(
                                    id = playlist.id,
                                    title = playlist.name,
                                    subtitle = subtitle,
                                    imageUrl = imageUrl,
                                    type = LibraryItemType.PLAYLIST
                                )
                            )
                            // Nota: no añadimos al playlistsMap para distinguir privadas vs públicas; navegación hace fallback
                        }
                    }
                }

                // 3) Playlists públicas marcadas como favoritas: incluir aunque no estén descargadas
                playlistsFromApi.filter { it.public && favorites.contains(it.id) }.forEach { playlist ->
                    if (seenPlaylistIds.add(playlist.id)) {
                        var imageUrl: String? = null
                        if (playlist.coverArt != null && musicRepository.serverUrl != null) {
                            val (u, t, s) = musicRepository.getAuthParams()
                            imageUrl = playlist.getCoverArtUrl(musicRepository.serverUrl!!, u, t, s, 200)
                        }
                        val subtitle = if (playlist.songCount > 0) "Playlist • ${playlist.songCount} canciones" else "Playlist"
                        newPlaylists.add(
                            LibraryItem(
                                id = playlist.id,
                                title = playlist.name,
                                subtitle = subtitle,
                                imageUrl = imageUrl,
                                type = LibraryItemType.PLAYLIST
                            )
                        )
                        // Añadir al mapa para navegación completa
                        newPlaylistsMap[playlist.id] = playlist
                    }
                }
            }.onFailure {
                // Si falla la API, al menos tenemos "Canciones que te gustan"
            }

            // De-duplicar por seguridad antes de asignar
            val finalPlaylists = newPlaylists.distinctBy { it.id }

            // Asignación atómica protegida por mutex para evitar interleavings
            playlistsMutex.withLock {
                playlists = finalPlaylists
                playlistsMap.clear()
                playlistsMap.putAll(newPlaylistsMap)
            }
        } catch (_: Exception) {
            // En caso de error, solo mantener "Canciones que te gustan"
            playlistsMutex.withLock {
                playlists = listOf(
                    LibraryItem(
                        id = "liked_songs",
                        title = "Canciones que te gustan",
                        subtitle = "Playlist • Tus favoritas",
                        imageUrl = null,
                        type = LibraryItemType.LIKED_SONGS
                    )
                )
                playlistsMap.clear()
            }
        }
    }

    private suspend fun loadAlbums() {
        try {
            val result = musicRepository.getStarredAlbums()
            result.onSuccess { albumsFromApi ->
                albums.clear()

                albumsFromApi.forEach { album ->
                    val (username, token, salt) = musicRepository.getAuthParams()
                    val imageUrl = ImageLoader.buildCoverArtUrl(
                        musicRepository.serverUrl!!,
                        album.id,
                        username,
                        token,
                        salt,
                        200
                    )

                    albums.add(
                        LibraryItem(
                            id = album.id,
                            title = album.name,
                            subtitle = "Álbum • ${album.artist}",
                            imageUrl = imageUrl,
                            type = LibraryItemType.ALBUM
                        )
                    )

                    // Agregar al mapa de álbumes
                    albumsMap[album.id] = album
                }
            }.onFailure {
                albums.clear()
            }
        } catch (_: Exception) {
            albums.clear()
        }
    }

    private suspend fun loadArtists() {
        try {
            val result = musicRepository.getStarredArtists()
            result.onSuccess { artistsFromApi ->
                artists.clear()

                artistsFromApi.forEach { artist ->
                    val (username, token, salt) = musicRepository.getAuthParams()
                    val imageUrl = ImageLoader.buildArtistImageUrl(
                        musicRepository.serverUrl!!,
                        artist.id,
                        username,
                        token,
                        salt,
                        200
                    )

                    // Construir subtítulo basado en si albumCount está disponible
                    val subtitle = if (artist.albumCount != null && artist.albumCount > 0) {
                        "Artista • ${artist.albumCount} álbumes"
                    } else {
                        "Artista"
                    }

                    artists.add(
                        LibraryItem(
                            id = artist.id,
                            title = artist.name,
                            subtitle = subtitle,
                            imageUrl = imageUrl,
                            type = LibraryItemType.ARTIST
                        )
                    )
                }
            }.onFailure {
                artists.clear()
            }
        } catch (_: Exception) {
            artists.clear()
        }
    }

    private fun buildAllItemsList() {
        allItems.clear()

        // Agregar en orden: playlists, álbumes, artistas (deduplicando defensivamente por ID)
        val uniquePlaylists = playlists.distinctBy { it.id }
        allItems.addAll(uniquePlaylists)
        allItems.addAll(albums)
        allItems.addAll(artists)
    }

    private fun filterContent() {
        if (currentFilter == "downloads") {
            filterDownloads()
            return
        }

        val filteredItems = when (currentFilter) {
            "all" -> allItems.toList()
            "playlists" -> playlists.distinctBy { it.id }
            "albums" -> albums.toList()
            "artists" -> artists.toList()
            else -> allItems.toList()
        }

        if (filteredItems.isEmpty()) {
            showEmptyState()
        } else {
            hideEmptyState()
            libraryAdapter.updateItems(filteredItems)
            // Scroll to top after applying the filter
            binding.rvLibraryItems.post {
                (binding.rvLibraryItems.layoutManager as? LinearLayoutManager)
                    ?.scrollToPositionWithOffset(0, 0)
            }
        }
    }

    private fun filterDownloads() {
        viewLifecycleOwner.lifecycleScope.launch {
            showLoading(true)
            try {
                // Recalcular descargas al entrar explícitamente a esta vista
                computeDownloadsIfNeeded(force = true)
                // Informar al adapter qué IDs están descargados solo si cambia
                val newIds = downloads.map { it.id }.toSet()
                if (newIds != lastDownloadedIds) {
                    lastDownloadedIds = newIds
                    libraryAdapter.updateDownloadedIds(newIds)
                }
                val filteredItems = downloads.toList()
                if (filteredItems.isEmpty()) {
                    showEmptyState()
                } else {
                    hideEmptyState()
                    libraryAdapter.updateItems(filteredItems)
                    // Scroll to top after applying the filter
                    binding.rvLibraryItems.post {
                        (binding.rvLibraryItems.layoutManager as? LinearLayoutManager)
                            ?.scrollToPositionWithOffset(0, 0)
                    }
                }
            } catch (e: Exception) {
                showError("Error al cargar descargados: ${e.message}")
            } finally {
                showLoading(false)
            }
        }
    }

    private suspend fun computeDownloadsIfNeeded(force: Boolean = false) {
        if (downloadsComputed && !force) return
        downloads.clear()
        if (force) {
            downloadedAlbumsCache.clear()
            downloadedPlaylistsCache.clear()
            downloadsComputed = false
        }

        val dm = SongDownloadManager.getInstance(requireContext())

        // Agregar Playlists descargadas (incluyendo públicas) y excluyendo 'liked_songs'
        try {
            val allPlaylists = musicRepository.getPlaylists().getOrNull().orEmpty()
            for (pl in allPlaylists) {
                // 'liked_songs' is a synthetic item, not part of API; skip by safety check
                if (pl.id == "liked_songs") continue

                val cached = downloadedPlaylistsCache[pl.id]
                val isDownloaded = if (cached != null) {
                    cached
                } else {
                    var fullyDownloaded = false
                    musicRepository.getPlaylistSongs(pl.id).onSuccess { songs ->
                        fullyDownloaded = songs.isNotEmpty() && songs.all { song ->
                            val path = dm.createDownloadPath(song)
                            File(path).exists()
                        }
                    }
                    downloadedPlaylistsCache[pl.id] = fullyDownloaded
                    fullyDownloaded
                }

                if (isDownloaded) {
                    // Try to reuse prepared LibraryItem from 'playlists' list (private ones)
                    val existing = playlists.find { it.id == pl.id }
                    if (existing != null) {
                        downloads.add(existing)
                    } else {
                        // Build a minimal LibraryItem for public playlists
                        val subtitle = if (pl.songCount > 0) "Playlist • ${pl.songCount} canciones" else "Playlist"
                        var imageUrl: String? = null
                        try {
                            if (pl.coverArt != null && musicRepository.serverUrl != null) {
                                val (u, t, s) = musicRepository.getAuthParams()
                                imageUrl = pl.getCoverArtUrl(musicRepository.serverUrl!!, u, t, s, 200)
                            }
                        } catch (_: Exception) { /* ignore */ }

                        downloads.add(
                            LibraryItem(
                                id = pl.id,
                                title = pl.name,
                                subtitle = subtitle,
                                imageUrl = imageUrl,
                                type = LibraryItemType.PLAYLIST
                            )
                        )
                    }
                }
            }
        } catch (_: Exception) {
            // ignore playlist download computation errors; keep others
        }

        // Agregar Álbumes descargados
        for (al in albumsMap.values) {
            val cached = downloadedAlbumsCache[al.id]
            val isDownloaded = if (cached != null) {
                cached
            } else {
                var fullyDownloaded = false
                musicRepository.getAlbumSongs(al.id).onSuccess { songs ->
                    fullyDownloaded = songs.isNotEmpty() && songs.all { song ->
                        val path = dm.createDownloadPath(song)
                        File(path).exists()
                    }
                }
                downloadedAlbumsCache[al.id] = fullyDownloaded
                fullyDownloaded
            }

            if (isDownloaded) {
                albums.find { it.id == al.id }?.let { item ->
                    downloads.add(item)
                } ?: run {
                    val (username, token, salt) = musicRepository.getAuthParams()
                    val imageUrl = ImageLoader.buildCoverArtUrl(
                        musicRepository.serverUrl!!,
                        al.id,
                        username,
                        token,
                        salt,
                        200
                    )
                    downloads.add(
                        LibraryItem(
                            id = al.id,
                            title = al.name,
                            subtitle = "Álbum • ${al.artist}",
                            imageUrl = imageUrl,
                            type = LibraryItemType.ALBUM
                        )
                    )
                }
            }
        }

        // Orden opcional: mantener orden por tipo como en allItems
        // Primero playlists, luego álbumes
        downloads.sortWith(compareBy({ it.type != LibraryItemType.PLAYLIST }, { it.title.lowercase() }))

        downloadsComputed = true
    }

    // Helper: show/hide Downloads chip based on whether there are downloaded items
    private fun updateDownloadsChipVisibility(force: Boolean = false) {
        viewLifecycleOwner.lifecycleScope.launch {
            try {
                computeDownloadsIfNeeded(force = force)
                val hasDownloads = downloads.isNotEmpty()
                val newIds = downloads.map { it.id }.toSet()

                // Siempre informar al adapter (el adapter puede ser nuevo tras recrear la vista)
                libraryAdapter.updateDownloadedIds(newIds)
                lastDownloadedIds = newIds

                if (!isAdded || _binding == null) return@launch

                // Reaplicar visibilidad siempre, ya que la vista pudo recrearse
                binding.chipDownloads.visibility = if (hasDownloads) View.VISIBLE else View.GONE
                lastDownloadsVisible = hasDownloads

                // If current filter is downloads but none available, fallback to 'all'
                if (!hasDownloads && currentFilter == "downloads") {
                    currentFilter = "all"
                    if (!isAdded || _binding == null) return@launch
                    applyCheckedChipFromFilter()
                    filterContent()
                }
            } catch (_: Exception) {
                if (!isAdded || _binding == null) return@launch
                // On error, hide downloads chip to avoid broken navigation
                lastDownloadsVisible = false
                binding.chipDownloads.visibility = View.GONE
                if (currentFilter == "downloads") {
                    currentFilter = "all"
                    applyCheckedChipFromFilter()
                    filterContent()
                }
            }
        }
    }

    private fun handleItemClick(item: LibraryItem) {
        // Congelar el RecyclerView y scroll antes de navegar para evitar efectos visuales
        binding.rvLibraryItems.isNestedScrollingEnabled = false
        binding.scrollFilters.isNestedScrollingEnabled = false

        // Forzar que los views se "asienten" antes de la transición
        binding.root.post {
            when (item.type) {
                LibraryItemType.PLAYLIST -> {
                    // Navegar a playlist específica
                    val playlist = playlistsMap[item.id]
                    if (playlist != null) {
                        val bundle = Bundle().apply {
                            putString("playlistId", playlist.id)
                            putString("playlistName", playlist.name)
                        }
                        findNavController().navigate(R.id.action_library_to_playlistDetail, bundle)
                    } else {
                        // Fallback: downloaded public playlist not present in playlists list
                        val bundle = Bundle().apply {
                            putString("playlistId", item.id)
                            putString("playlistName", item.title)
                        }
                        findNavController().navigate(R.id.action_library_to_playlistDetail, bundle)
                    }
                }
                LibraryItemType.ARTIST -> {
                    val bundle = Bundle().apply {
                        putString("artistId", item.id)
                        putString("artistName", item.title)
                    }
                    // Usar la acción definida en nav_graph para asegurar que las animaciones se ejecuten
                    findNavController().navigate(R.id.action_library_to_artistDetail, bundle)
                }
                LibraryItemType.ALBUM -> {
                    // Navegar a detalle de álbum usando la acción del nav_graph
                    val album = albumsMap[item.id]
                    if (album != null) {
                        val bundle = Bundle().apply {
                            putParcelable("album", album)
                        }
                        // Usar la acción definida en nav_graph para asegurar que las animaciones se ejecuten
                        findNavController().navigate(R.id.action_library_to_albumDetail, bundle)
                    }
                }
                LibraryItemType.LIKED_SONGS -> {
                    // Navegar a canciones favoritas con animaciones definidas
                    findNavController().navigate(R.id.action_library_to_favorites)
                }
            }
        }
    }

    private fun showLoading(show: Boolean) {
        if (_binding == null) return
        binding.progressBar.visibility = if (show) View.VISIBLE else View.GONE
        binding.rvLibraryItems.visibility = if (show) View.GONE else View.VISIBLE
    }

    @Suppress("UNUSED_PARAMETER")
    private fun showError(message: String) {
        if (_binding == null) return
        binding.layoutEmpty.visibility = View.VISIBLE
        binding.rvLibraryItems.visibility = View.GONE
        // TODO: Mostrar mensaje de error específico
    }

    private fun showEmptyState() {
        if (_binding == null) return
        binding.rvLibraryItems.visibility = View.GONE
        binding.layoutEmpty.visibility = View.VISIBLE
    }

    private fun hideEmptyState() {
        if (_binding == null) return
        binding.layoutEmpty.visibility = View.GONE
        binding.rvLibraryItems.visibility = View.VISIBLE
    }

    override fun onDestroyView() {
        super.onDestroyView()
        _binding = null
    }

    override fun onResume() {
        super.onResume()
        // Aplicar el color estático consistente de la app
        StatusBarUtils.setStatusBarColor(this)

        // Restaurar el comportamiento de scroll normal cuando regresemos al fragmento
        if (_binding != null) {
            binding.rvLibraryItems.isNestedScrollingEnabled = true
            binding.scrollFilters.isNestedScrollingEnabled = true
            // Reaplicar colores de chips en caso de que el estado visual haya sido alterado
            applyCheckedChipFromFilter()
            // Re-evaluar descargas por si cambiaron fuera de este fragmento (sin forzar si ya está calculado)
            updateDownloadsChipVisibility(force = false)

            // Refrescar listas para reflejar cambios de favoritos de playlists públicas
            viewLifecycleOwner.lifecycleScope.launch {
                try {
                    loadPlaylists()
                    buildAllItemsList()
                    filterContent()
                } catch (_: Exception) { /* ignore refresh errors */ }
            }
        }
    }

    override fun onSaveInstanceState(outState: Bundle) {
        super.onSaveInstanceState(outState)
        outState.putString("currentFilter", currentFilter)
    }
}

package com.arantec.castafiore.ui.fragments

import android.os.Bundle
import android.view.LayoutInflater
import android.view.View
import android.view.ViewGroup
import androidx.fragment.app.Fragment
import androidx.navigation.fragment.findNavController
import androidx.recyclerview.widget.LinearLayoutManager
import androidx.lifecycle.lifecycleScope
import kotlinx.coroutines.launch
import com.arantec.castafiore.R
import com.arantec.castafiore.databinding.FragmentLibraryBinding
import com.arantec.castafiore.ui.adapters.LibraryAdapter
import com.arantec.castafiore.data.models.LibraryItem
import com.arantec.castafiore.data.models.LibraryItemType
import com.arantec.castafiore.data.models.Album
import com.arantec.castafiore.data.models.Playlist
import com.arantec.castafiore.data.repository.MusicRepository
import com.arantec.castafiore.utils.ImageLoader
import com.arantec.castafiore.utils.StatusBarUtils
import com.google.android.material.chip.Chip
import com.arantec.castafiore.data.download.SongDownloadManager
import com.arantec.castafiore.utils.PlaylistFavoritesManager
import java.io.File
import com.arantec.castafiore.ui.helpers.HasContentState
import com.arantec.castafiore.ui.helpers.LoadingHost
import kotlinx.coroutines.sync.Mutex
import kotlinx.coroutines.sync.withLock

class LibraryFragment : Fragment(), HasContentState {

    private var _binding: FragmentLibraryBinding? = null
    private val binding get() = _binding!!

    private lateinit var libraryAdapter: LibraryAdapter
    private lateinit var musicRepository: MusicRepository
    private var currentFilter = "all"

    // Listas de datos separadas por tipo
    private var allItems = mutableListOf<LibraryItem>()
    private var playlists: List<LibraryItem> = emptyList()
    private var albums = mutableListOf<LibraryItem>()
    private var artists = mutableListOf<LibraryItem>()

    // Mapas para mantener referencias a los objetos completos
    private var albumsMap = mutableMapOf<String, Album>()
    private var playlistsMap = mutableMapOf<String, Playlist>()

    // Mutex para evitar condiciones de carrera al actualizar playlists
    private val playlistsMutex = Mutex()

    // Descargas
    private var downloads = mutableListOf<LibraryItem>()
    private var downloadsComputed = false
    private var downloadedAlbumsCache = mutableMapOf<String, Boolean>()
    private var downloadedPlaylistsCache = mutableMapOf<String, Boolean>()
    // Estado para evitar parpadeo y actualizaciones redundantes
    private var lastDownloadsVisible: Boolean = false
    private var lastDownloadedIds: Set<String> = emptySet()

    private fun loadingHost(): LoadingHost? = activity as? LoadingHost

    override fun hasContent(): Boolean {
        return this::libraryAdapter.isInitialized && libraryAdapter.itemCount > 0
    }

    override fun onCreateView(
        inflater: LayoutInflater,
        container: ViewGroup?,
        savedInstanceState: Bundle?
    ): View {
        _binding = FragmentLibraryBinding.inflate(inflater, container, false)
        return binding.root
    }

    override fun onViewCreated(view: View, savedInstanceState: Bundle?) {
        super.onViewCreated(view, savedInstanceState)

        musicRepository = MusicRepository.getInstance(requireContext())

        // Asegurar que el contenido no se dibuje bajo la status bar, sin añadir insets inferiores
        StatusBarUtils.applyStatusBarTopPadding(binding.root)

        // Restaurar filtro si viene de estado guardado
        savedInstanceState?.getString("currentFilter")?.let { restored ->
            currentFilter = restored
        }

        setupRecyclerView()
        setupFilters()
        setupControls()

        // Asegurar que el chip resaltado corresponda al filtro actual
        applyCheckedChipFromFilter()

        loadInitialData()
    }

    private fun setupRecyclerView() {
        libraryAdapter = LibraryAdapter { item ->
            handleItemClick(item)
        }

        binding.rvLibraryItems.apply {
            layoutManager = LinearLayoutManager(requireContext())
            adapter = libraryAdapter
        }

        // Asegurar que el adapter nuevo conozca los IDs descargados ya calculados
        if (lastDownloadedIds.isNotEmpty()) {
            libraryAdapter.updateDownloadedIds(lastDownloadedIds)
        }
    }

    private fun setupFilters() {
        // Configurar chips de filtros con manejo mejorado
        binding.chipAll.setOnClickListener {
            selectChip(binding.chipAll, "all")
        }

        binding.chipPlaylists.setOnClickListener {
            selectChip(binding.chipPlaylists, "playlists")
        }

        binding.chipAlbums.setOnClickListener {
            selectChip(binding.chipAlbums, "albums")
        }

        binding.chipArtists.setOnClickListener {
            selectChip(binding.chipArtists, "artists")
        }

        binding.chipDownloads.setOnClickListener {
            selectChip(binding.chipDownloads, "downloads")
        }
    }

    private fun selectChip(selectedChip: Chip, filter: String) {
        // Desmarcar todos los chips sin disparar listeners
        val chips = listOf(
            binding.chipAll,
            binding.chipDownloads,
            binding.chipPlaylists,
            binding.chipAlbums,
            binding.chipArtists
        )
        chips.forEach { chip ->
            chip.isChecked = false
        }

        // Marcar el chip seleccionado
        selectedChip.isChecked = true

        // Aplicar filtro
        currentFilter = filter
        filterContent()

        // Actualizar colores visuales
        updateChipColors()
    }

    private fun updateChipColors() {
        val primaryColor = androidx.core.content.ContextCompat.getColor(requireContext(), R.color.primary)
        val onPrimaryColor = androidx.core.content.ContextCompat.getColor(requireContext(), R.color.on_primary)
        val onSurfaceColor = androidx.core.content.ContextCompat.getColor(requireContext(), R.color.on_surface)
        val outlineColor = androidx.core.content.ContextCompat.getColor(requireContext(), R.color.outline)

        val chips = listOf(
            binding.chipAll,
            binding.chipDownloads,
            binding.chipPlaylists,
            binding.chipAlbums,
            binding.chipArtists
        )

        chips.forEach { chip ->
            if (chip.isChecked) {
                // Selected: filled primary background, white text, no stroke
                chip.chipBackgroundColor = android.content.res.ColorStateList.valueOf(primaryColor)
                chip.setTextColor(onPrimaryColor)
                chip.chipStrokeColor = android.content.res.ColorStateList.valueOf(primaryColor)
                chip.chipStrokeWidth = 0f
                chip.isChipIconVisible = false
            } else {
                // Unselected: transparent background, on-surface text, outline stroke
                chip.chipBackgroundColor = android.content.res.ColorStateList.valueOf(android.graphics.Color.TRANSPARENT)
                chip.setTextColor(onSurfaceColor)
                chip.chipStrokeColor = android.content.res.ColorStateList.valueOf(outlineColor)
                chip.chipStrokeWidth = 1f
                chip.isChipIconVisible = false
            }
        }
    }

    private fun applyCheckedChipFromFilter() {
        // Establecer el checked real según el filtro actual y luego pintar
        val isAll = currentFilter == "all"
        val isPlaylists = currentFilter == "playlists"
        val isAlbums = currentFilter == "albums"
        val isArtists = currentFilter == "artists"
        val isDownloads = currentFilter == "downloads"

        binding.chipAll.isChecked = isAll
        binding.chipPlaylists.isChecked = isPlaylists
        binding.chipAlbums.isChecked = isAlbums
        binding.chipArtists.isChecked = isArtists
        binding.chipDownloads.isChecked = isDownloads

        updateChipColors()
    }

    private fun setupControls() {
        binding.tvSortBy.setOnClickListener {
            // TODO: Mostrar opciones de ordenamiento
        }

        binding.btnViewMode.setOnClickListener {
            // TODO: Cambiar entre vista lista y cuadrícula
        }

        binding.actionLibraryToSearch.setOnClickListener {
            // Navegar al buscador
            findNavController().navigate(R.id.action_library_to_search)
        }
    }

    private fun loadInitialData() {
        // Only show local loader if we already have content (refresh behavior)
        if (hasContent()) {
            showLoading(true)
        } else {
            // Cold start without content: ensure global overlay is visible as fallback
            loadingHost()?.showGlobalLoading(true)
        }

        viewLifecycleOwner.lifecycleScope.launch {
            try {
                // Cargar datos por separado
                loadPlaylists()
                loadAlbums()
                loadArtists()

                // Una vez cargado todo, construir lista completa y mostrar contenido
                buildAllItemsList()
                filterContent()

                // Actualizar visibilidad del chip de Descargados (forzar primer cálculo)
                updateDownloadsChipVisibility(force = true)

            } catch (e: Exception) {
                showError("Error al cargar la biblioteca: ${e.message}")
            } finally {
                // Always hide global overlay after finishing initial load (success or error)
                loadingHost()?.showGlobalLoading(false)
                showLoading(false)
            }
        }
    }

    private suspend fun loadPlaylists() {
        try {
            // Construir listas locales para asignar de forma atómica y evitar duplicados por cargas concurrentes
            val newPlaylists = mutableListOf<LibraryItem>()
            val newPlaylistsMap = mutableMapOf<String, Playlist>()

            // Conjunto para evitar duplicados por ID (robusto ante respuestas repetidas de API)
            val seenPlaylistIds = mutableSetOf<String>()
            // Siempre agregar "Canciones que te gustan" primero
            newPlaylists.add(
                LibraryItem(
                    id = "liked_songs",
                    title = "Canciones que te gustan",
                    subtitle = "Playlist • Tus favoritas",
                    imageUrl = null,
                    type = LibraryItemType.LIKED_SONGS
                )
            )
            seenPlaylistIds.add("liked_songs")

            // Luego cargar las playlists de la API
            val result = musicRepository.getPlaylists()
            result.onSuccess { playlistsFromApi ->
                val dm = SongDownloadManager.getInstance(requireContext())
                val favorites = PlaylistFavoritesManager.getFavorites(requireContext())

                // 1) Playlists privadas (siempre)
                playlistsFromApi.filter { !it.public }.forEach { playlist ->
                    if (seenPlaylistIds.add(playlist.id)) {
                        val subtitle = "${playlist.songCount} canciones"

                        // Construir URL de imagen si la playlist tiene coverArt
                        var imageUrl: String? = null
                        if (playlist.coverArt != null) {
                            val (username, token, salt) = musicRepository.getAuthParams()
                            imageUrl = playlist.getCoverArtUrl(
                                musicRepository.serverUrl!!,
                                username,
                                token,
                                salt,
                                200
                            )
                        }

                        newPlaylists.add(
                            LibraryItem(
                                id = playlist.id,
                                title = playlist.name,
                                subtitle = "Playlist • $subtitle",
                                imageUrl = imageUrl,
                                type = LibraryItemType.PLAYLIST
                            )
                        )

                        // Agregar al mapa de playlists
                        newPlaylistsMap[playlist.id] = playlist
                    }
                }

                // 2) Playlists públicas descargadas: incluir también en listas principales
                playlistsFromApi.filter { it.public }.forEach { playlist ->
                    // Comprobar si está completamente descargada
                    var fullyDownloaded = false
                    try {
                        musicRepository.getPlaylistSongs(playlist.id).onSuccess { songs ->
                            fullyDownloaded = songs.isNotEmpty() && songs.all { song ->
                                val path = dm.createDownloadPath(song)
                                java.io.File(path).exists()
                            }
                        }
                    } catch (_: Exception) { /* ignore */ }

                    if (fullyDownloaded) {
                        if (seenPlaylistIds.add(playlist.id)) {
                            var imageUrl: String? = null
                            if (playlist.coverArt != null && musicRepository.serverUrl != null) {
                                val (u, t, s) = musicRepository.getAuthParams()
                                imageUrl = playlist.getCoverArtUrl(musicRepository.serverUrl!!, u, t, s, 200)
                            }
                            val subtitle = if (playlist.songCount > 0) "Playlist • ${playlist.songCount} canciones" else "Playlist"
                            newPlaylists.add(
                                LibraryItem(
                                    id = playlist.id,
                                    title = playlist.name,
                                    subtitle = subtitle,
                                    imageUrl = imageUrl,
                                    type = LibraryItemType.PLAYLIST
                                )
                            )
                            // Nota: no añadimos al playlistsMap para distinguir privadas vs públicas; navegación hace fallback
                        }
                    }
                }

                // 3) Playlists públicas marcadas como favoritas: incluir aunque no estén descargadas
                playlistsFromApi.filter { it.public && favorites.contains(it.id) }.forEach { playlist ->
                    if (seenPlaylistIds.add(playlist.id)) {
                        var imageUrl: String? = null
                        if (playlist.coverArt != null && musicRepository.serverUrl != null) {
                            val (u, t, s) = musicRepository.getAuthParams()
                            imageUrl = playlist.getCoverArtUrl(musicRepository.serverUrl!!, u, t, s, 200)
                        }
                        val subtitle = if (playlist.songCount > 0) "Playlist • ${playlist.songCount} canciones" else "Playlist"
                        newPlaylists.add(
                            LibraryItem(
                                id = playlist.id,
                                title = playlist.name,
                                subtitle = subtitle,
                                imageUrl = imageUrl,
                                type = LibraryItemType.PLAYLIST
                            )
                        )
                        // Añadir al mapa para navegación completa
                        newPlaylistsMap[playlist.id] = playlist
                    }
                }
            }.onFailure {
                // Si falla la API, al menos tenemos "Canciones que te gustan"
            }

            // De-duplicar por seguridad antes de asignar
            val finalPlaylists = newPlaylists.distinctBy { it.id }

            // Asignación atómica protegida por mutex para evitar interleavings
            playlistsMutex.withLock {
                playlists = finalPlaylists
                playlistsMap.clear()
                playlistsMap.putAll(newPlaylistsMap)
            }
        } catch (_: Exception) {
            // En caso de error, solo mantener "Canciones que te gustan"
            playlistsMutex.withLock {
                playlists = listOf(
                    LibraryItem(
                        id = "liked_songs",
                        title = "Canciones que te gustan",
                        subtitle = "Playlist • Tus favoritas",
                        imageUrl = null,
                        type = LibraryItemType.LIKED_SONGS
                    )
                )
                playlistsMap.clear()
            }
        }
    }

    private suspend fun loadAlbums() {
        try {
            val result = musicRepository.getStarredAlbums()
            result.onSuccess { albumsFromApi ->
                albums.clear()

                albumsFromApi.forEach { album ->
                    val (username, token, salt) = musicRepository.getAuthParams()
                    val imageUrl = ImageLoader.buildCoverArtUrl(
                        musicRepository.serverUrl!!,
                        album.id,
                        username,
                        token,
                        salt,
                        200
                    )

                    albums.add(
                        LibraryItem(
                            id = album.id,
                            title = album.name,
                            subtitle = "Álbum • ${album.artist}",
                            imageUrl = imageUrl,
                            type = LibraryItemType.ALBUM
                        )
                    )

                    // Agregar al mapa de álbumes
                    albumsMap[album.id] = album
                }
            }.onFailure {
                albums.clear()
            }
        } catch (_: Exception) {
            albums.clear()
        }
    }

    private suspend fun loadArtists() {
        try {
            val result = musicRepository.getStarredArtists()
            result.onSuccess { artistsFromApi ->
                artists.clear()

                artistsFromApi.forEach { artist ->
                    val (username, token, salt) = musicRepository.getAuthParams()
                    val imageUrl = ImageLoader.buildArtistImageUrl(
                        musicRepository.serverUrl!!,
                        artist.id,
                        username,
                        token,
                        salt,
                        200
                    )

                    // Construir subtítulo basado en si albumCount está disponible
                    val subtitle = if (artist.albumCount != null && artist.albumCount > 0) {
                        "Artista • ${artist.albumCount} álbumes"
                    } else {
                        "Artista"
                    }

                    artists.add(
                        LibraryItem(
                            id = artist.id,
                            title = artist.name,
                            subtitle = subtitle,
                            imageUrl = imageUrl,
                            type = LibraryItemType.ARTIST
                        )
                    )
                }
            }.onFailure {
                artists.clear()
            }
        } catch (_: Exception) {
            artists.clear()
        }
    }

    private fun buildAllItemsList() {
        allItems.clear()

        // Agregar en orden: playlists, álbumes, artistas (deduplicando defensivamente por ID)
        val uniquePlaylists = playlists.distinctBy { it.id }
        allItems.addAll(uniquePlaylists)
        allItems.addAll(albums)
        allItems.addAll(artists)
    }

    private fun filterContent() {
        if (currentFilter == "downloads") {
            filterDownloads()
            return
        }

        val filteredItems = when (currentFilter) {
            "all" -> allItems.toList()
            "playlists" -> playlists.distinctBy { it.id }
            "albums" -> albums.toList()
            "artists" -> artists.toList()
            else -> allItems.toList()
        }

        if (filteredItems.isEmpty()) {
            showEmptyState()
        } else {
            hideEmptyState()
            libraryAdapter.updateItems(filteredItems)
            // Scroll to top after applying the filter
            binding.rvLibraryItems.post {
                (binding.rvLibraryItems.layoutManager as? LinearLayoutManager)
                    ?.scrollToPositionWithOffset(0, 0)
            }
        }
    }

    private fun filterDownloads() {
        viewLifecycleOwner.lifecycleScope.launch {
            // Ensure global overlay is not blocking interactions in this local-only compute
            loadingHost()?.showGlobalLoading(false)
            showLoading(true)
            try {
                // Recalcular descargas al entrar explícitamente a esta vista
                computeDownloadsIfNeeded(force = true)
                // Informar al adapter qué IDs están descargados solo si cambia
                val newIds = downloads.map { it.id }.toSet()
                if (newIds != lastDownloadedIds) {
                    lastDownloadedIds = newIds
                    libraryAdapter.updateDownloadedIds(newIds)
                }
                val filteredItems = downloads.toList()
                if (filteredItems.isEmpty()) {
                    showEmptyState()
                } else {
                    hideEmptyState()
                    libraryAdapter.updateItems(filteredItems)
                    // Scroll to top after applying the filter
                    binding.rvLibraryItems.post {
                        (binding.rvLibraryItems.layoutManager as? LinearLayoutManager)
                            ?.scrollToPositionWithOffset(0, 0)
                    }
                }
            } catch (e: Exception) {
                showError("Error al cargar descargados: ${e.message}")
            } finally {
                showLoading(false)
            }
        }
    }

    private suspend fun computeDownloadsIfNeeded(force: Boolean = false) {
        if (downloadsComputed && !force) return
        downloads.clear()
        if (force) {
            downloadedAlbumsCache.clear()
            downloadedPlaylistsCache.clear()
            downloadsComputed = false
        }

        val dm = SongDownloadManager.getInstance(requireContext())

        // Agregar Playlists descargadas (incluyendo públicas) y excluyendo 'liked_songs'
        try {
            val allPlaylists = musicRepository.getPlaylists().getOrNull().orEmpty()
            for (pl in allPlaylists) {
                // 'liked_songs' is a synthetic item, not part of API; skip by safety check
                if (pl.id == "liked_songs") continue

                val cached = downloadedPlaylistsCache[pl.id]
                val isDownloaded = if (cached != null) {
                    cached
                } else {
                    var fullyDownloaded = false
                    musicRepository.getPlaylistSongs(pl.id).onSuccess { songs ->
                        fullyDownloaded = songs.isNotEmpty() && songs.all { song ->
                            val path = dm.createDownloadPath(song)
                            File(path).exists()
                        }
                    }
                    downloadedPlaylistsCache[pl.id] = fullyDownloaded
                    fullyDownloaded
                }

                if (isDownloaded) {
                    // Try to reuse prepared LibraryItem from 'playlists' list (private ones)
                    val existing = playlists.find { it.id == pl.id }
                    if (existing != null) {
                        downloads.add(existing)
                    } else {
                        // Build a minimal LibraryItem for public playlists
                        val subtitle = if (pl.songCount > 0) "Playlist • ${pl.songCount} canciones" else "Playlist"
                        var imageUrl: String? = null
                        try {
                            if (pl.coverArt != null && musicRepository.serverUrl != null) {
                                val (u, t, s) = musicRepository.getAuthParams()
                                imageUrl = pl.getCoverArtUrl(musicRepository.serverUrl!!, u, t, s, 200)
                            }
                        } catch (_: Exception) { /* ignore */ }

                        downloads.add(
                            LibraryItem(
                                id = pl.id,
                                title = pl.name,
                                subtitle = subtitle,
                                imageUrl = imageUrl,
                                type = LibraryItemType.PLAYLIST
                            )
                        )
                    }
                }
            }
        } catch (_: Exception) {
            // ignore playlist download computation errors; keep others
        }

        // Agregar Álbumes descargados
        for (al in albumsMap.values) {
            val cached = downloadedAlbumsCache[al.id]
            val isDownloaded = if (cached != null) {
                cached
            } else {
                var fullyDownloaded = false
                musicRepository.getAlbumSongs(al.id).onSuccess { songs ->
                    fullyDownloaded = songs.isNotEmpty() && songs.all { song ->
                        val path = dm.createDownloadPath(song)
                        File(path).exists()
                    }
                }
                downloadedAlbumsCache[al.id] = fullyDownloaded
                fullyDownloaded
            }

            if (isDownloaded) {
                albums.find { it.id == al.id }?.let { item ->
                    downloads.add(item)
                } ?: run {
                    val (username, token, salt) = musicRepository.getAuthParams()
                    val imageUrl = ImageLoader.buildCoverArtUrl(
                        musicRepository.serverUrl!!,
                        al.id,
                        username,
                        token,
                        salt,
                        200
                    )
                    downloads.add(
                        LibraryItem(
                            id = al.id,
                            title = al.name,
                            subtitle = "Álbum • ${al.artist}",
                            imageUrl = imageUrl,
                            type = LibraryItemType.ALBUM
                        )
                    )
                }
            }
        }

        // Orden opcional: mantener orden por tipo como en allItems
        // Primero playlists, luego álbumes
        downloads.sortWith(compareBy({ it.type != LibraryItemType.PLAYLIST }, { it.title.lowercase() }))

        downloadsComputed = true
    }

    // Helper: show/hide Downloads chip based on whether there are downloaded items
    private fun updateDownloadsChipVisibility(force: Boolean = false) {
        viewLifecycleOwner.lifecycleScope.launch {
            try {
                computeDownloadsIfNeeded(force = force)
                val hasDownloads = downloads.isNotEmpty()
                val newIds = downloads.map { it.id }.toSet()

                // Siempre informar al adapter (el adapter puede ser nuevo tras recrear la vista)
                libraryAdapter.updateDownloadedIds(newIds)
                lastDownloadedIds = newIds

                if (!isAdded || _binding == null) return@launch

                // Reaplicar visibilidad siempre, ya que la vista pudo recrearse
                binding.chipDownloads.visibility = if (hasDownloads) View.VISIBLE else View.GONE
                lastDownloadsVisible = hasDownloads

                // If current filter is downloads but none available, fallback to 'all'
                if (!hasDownloads && currentFilter == "downloads") {
                    currentFilter = "all"
                    if (!isAdded || _binding == null) return@launch
                    applyCheckedChipFromFilter()
                    filterContent()
                }
            } catch (_: Exception) {
                if (!isAdded || _binding == null) return@launch
                // On error, hide downloads chip to avoid broken navigation
                lastDownloadsVisible = false
                binding.chipDownloads.visibility = View.GONE
                if (currentFilter == "downloads") {
                    currentFilter = "all"
                    applyCheckedChipFromFilter()
                    filterContent()
                }
            }
        }
    }

    private fun handleItemClick(item: LibraryItem) {
        // Congelar el RecyclerView y scroll antes de navegar para evitar efectos visuales
        binding.rvLibraryItems.isNestedScrollingEnabled = false
        binding.scrollFilters.isNestedScrollingEnabled = false

        // Forzar que los views se "asienten" antes de la transición
        binding.root.post {
            when (item.type) {
                LibraryItemType.PLAYLIST -> {
                    // Navegar a playlist específica
                    val playlist = playlistsMap[item.id]
                    if (playlist != null) {
                        val bundle = Bundle().apply {
                            putString("playlistId", playlist.id)
                            putString("playlistName", playlist.name)
                        }
                        findNavController().navigate(R.id.action_library_to_playlistDetail, bundle)
                    } else {
                        // Fallback: downloaded public playlist not present in playlists list
                        val bundle = Bundle().apply {
                            putString("playlistId", item.id)
                            putString("playlistName", item.title)
                        }
                        findNavController().navigate(R.id.action_library_to_playlistDetail, bundle)
                    }
                }
                LibraryItemType.ARTIST -> {
                    val bundle = Bundle().apply {
                        putString("artistId", item.id)
                        putString("artistName", item.title)
                    }
                    // Usar la acción definida en nav_graph para asegurar que las animaciones se ejecuten
                    findNavController().navigate(R.id.action_library_to_artistDetail, bundle)
                }
                LibraryItemType.ALBUM -> {
                    // Navegar a detalle de álbum usando la acción del nav_graph
                    val album = albumsMap[item.id]
                    if (album != null) {
                        val bundle = Bundle().apply {
                            putParcelable("album", album)
                        }
                        // Usar la acción definida en nav_graph para asegurar que las animaciones se ejecuten
                        findNavController().navigate(R.id.action_library_to_albumDetail, bundle)
                    }
                }
                LibraryItemType.LIKED_SONGS -> {
                    // Navegar a canciones favoritas con animaciones definidas
                    findNavController().navigate(R.id.action_library_to_favorites)
                }
            }
        }
    }

    private fun showLoading(show: Boolean) {
        if (_binding == null) return
        // If we are showing the fragment-level loader, ensure the global overlay is not blocking
        if (show) loadingHost()?.showGlobalLoading(false)
        binding.progressBar.visibility = if (show) View.VISIBLE else View.GONE
        binding.rvLibraryItems.visibility = if (show) View.GONE else View.VISIBLE
    }

    @Suppress("UNUSED_PARAMETER")
    private fun showError(message: String) {
        if (_binding == null) return
        binding.layoutEmpty.visibility = View.VISIBLE
        binding.rvLibraryItems.visibility = View.GONE
        // TODO: Mostrar mensaje de error específico
    }

    private fun showEmptyState() {
        if (_binding == null) return
        binding.rvLibraryItems.visibility = View.GONE
        binding.layoutEmpty.visibility = View.VISIBLE
    }

    private fun hideEmptyState() {
        if (_binding == null) return
        binding.layoutEmpty.visibility = View.GONE
        binding.rvLibraryItems.visibility = View.VISIBLE
    }

    override fun onDestroyView() {
        super.onDestroyView()
        // Safety: ensure global overlay isn't left visible when the view is destroyed
        loadingHost()?.showGlobalLoading(false)
        _binding = null
    }

    override fun onResume() {
        super.onResume()
        // Aplicar el color estático consistente de la app
        StatusBarUtils.setStatusBarColor(this)

        // Restaurar el comportamiento de scroll normal cuando regresemos al fragmento
        if (_binding != null) {
            binding.rvLibraryItems.isNestedScrollingEnabled = true
            binding.scrollFilters.isNestedScrollingEnabled = true
            // Reaplicar colores de chips en caso de que el estado visual haya sido alterado
            applyCheckedChipFromFilter()
            // Re-evaluar descargas por si cambiaron fuera de este fragmento (sin forzar si ya está calculado)
            updateDownloadsChipVisibility(force = false)

            // Refrescar listas para reflejar cambios de favoritos de playlists públicas
            viewLifecycleOwner.lifecycleScope.launch {
                try {
                    loadPlaylists()
                    buildAllItemsList()
                    filterContent()
                } catch (_: Exception) { /* ignore refresh errors */ }
            }
        }
    }

    override fun onSaveInstanceState(outState: Bundle) {
        super.onSaveInstanceState(outState)
        outState.putString("currentFilter", currentFilter)
    }
}
